from base.service import BaseServicefrom helpers.search import Paginationfrom models.container import Containerfrom repositories.container import ContainerRepositoryfrom schemas.container import FullContainerShowfrom sqlalchemy.ext.asyncio import AsyncSessionfrom DTO.container import ContainerDTO, ContainerWithAuthorDTOfrom models.container import ContainerTypefrom utils.container import ContainerSearchParamsfrom helpers.search import Paginationclass ContainerService(BaseService[Container, ContainerRepository, ContainerDTO]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)    async def search_container(            self, type_: ContainerType,            search: ContainerSearchParams,            pagination: Pagination    ) -> list[ContainerWithAuthorDTO]:        containers = await self.repository.search(            type_=type_, **pagination.dict(), **search.dict()        )        return containers